#!/bin/sh
set -eu
# PassWall2 exempts packets whose low byte is 255. Preserve zapret2's high
# bits and add that exemption only to packets generated by nfqws2 itself.
# Ordinary Xray direct connections can still be processed by zapret2.
nft 'insert rule inet zapret2 predefrag meta mark and 0x40000000 != 0 meta mark set meta mark or 0xff counter comment "nfqws2 bypass PassWall2"'
